package vn.biz04.web;

import jakarta.servlet.http.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.WebDataBinder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.ExtendedServletRequestDataBinder;
import org.springframework.validation.BindingResult;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.security.access.AccessDeniedException;
import vn.biz04.data.Store;
import vn.biz04.domain.NguoiDung;
import vn.biz04.service.*;
import java.security.Principal;
import java.time.*;
import java.util.*;

@Controller
public class MilestonePlanWeb {
    private final MilestonePlanService plans;private final Store db;private final TransactionTemplate tx;private final Clock clock;
    public MilestonePlanWeb(MilestonePlanService plans,Store db,TransactionTemplate tx,Clock clock){this.plans=plans;this.db=db;this.tx=tx;this.clock=clock;}
    private record Intent(Long actor,String kind,Long id,int version,String fingerprint,String operation,Instant expires){}
    private record Ticket(Intent intent,String action,MilestonePlanRules.Terms terms,String reason){}
    @ModelAttribute("emptyMilestoneRow") MilestonePlanForm.Item emptyRow(){return new MilestonePlanForm.Item();}
    public static class CancelForm {private String reason="";public String getReason(){return reason;}public void setReason(String value){reason=value;}}
    private static final Set<String> BUSINESS;
    static{Set<String> fields=new HashSet<>(Set.of("mode","reason"));for(int i=0;i<10;i++)for(String name:List.of("stableKey","title","work","deliverable","criteria","due","amount","revisions"))fields.add("items["+i+"]."+name);BUSINESS=Set.copyOf(fields);}
    @InitBinder("planForm") void planFields(WebDataBinder binder){binder.setAllowedFields(BUSINESS.toArray(String[]::new));binder.setAutoGrowCollectionLimit(10);if(binder instanceof ExtendedServletRequestDataBinder servlet)servlet.addHeaderPredicate(header->false);}
    @InitBinder("cancelForm") void cancelFields(WebDataBinder binder){binder.setAllowedFields("reason");if(binder instanceof ExtendedServletRequestDataBinder servlet)servlet.addHeaderPredicate(header->false);}
    private Long actor(Principal p){if(p==null)throw new AccessDeniedException("Cần đăng nhập.");return tx.execute(s->db.first("from NguoiDung u where u.email=:e and u.trangThai='HOAT_DONG'",NguoiDung.class,"e",p.getName()).orElseThrow(()->new AccessDeniedException("Tài khoản không hoạt động.")).getMaNguoiDung());}
    private String url(String kind,Long id){return "/ke-hoach-moc/"+kind+"/"+id;}
    private Intent intent(Long actor,MilestonePlanService.View view){return new Intent(actor,view.source().kind(),view.source().id(),view.current(),view.source().fingerprint(),UUID.randomUUID().toString(),clock.instant().plus(Duration.ofMinutes(30)));}
    @SuppressWarnings("unchecked") private String remember(HttpSession session,String group,Object value){synchronized(session){Map<String,Object> values=(Map<String,Object>)session.getAttribute(group);if(values==null){values=new LinkedHashMap<>();session.setAttribute(group,values);}String key=UUID.randomUUID().toString();values.put(key,value);while(values.size()>32)values.remove(values.keySet().iterator().next());return key;}}
    private <T> T stored(HttpSession session,String group,String token,Class<T> type){synchronized(session){Object raw=session.getAttribute(group);Object value=raw instanceof Map<?,?> map?map.get(token):null;Checks.require(type.isInstance(value),"Phiên rà soát đã hết hạn. Hãy mở lại kế hoạch và rà soát; các phiên bản đã gửi vẫn được giữ.");return type.cast(value);}}
    private void authority(Intent intent,Long actor,String kind,Long id){if(!intent.actor().equals(actor)||!intent.kind().equals(kind)||!intent.id().equals(id))throw new AccessDeniedException("Phiên rà soát không thuộc tài khoản hoặc nguồn này.");Checks.require(clock.instant().isBefore(intent.expires()),"Phiên rà soát đã hết hạn. Hãy mở lại kế hoạch và rà soát; các phiên bản đã gửi vẫn được giữ.");}
    private void bound(BindingResult binding,HttpServletRequest request,Set<String> allowed){Checks.require(!binding.hasErrors()&&Arrays.stream(binding.getSuppressedFields()).allMatch(Set.of("token","_csrf","kind","sourceId")::contains)&&request.getParameterMap().keySet().stream().allMatch(k->allowed.contains(k)||Set.of("token","_csrf").contains(k)),"Biểu mẫu chứa trường không được phép cập nhật.");}
    @ExceptionHandler(BusinessException.class) String failed(BusinessException error,HttpServletRequest request,Principal p,Model model){model.addAttribute("error",error.getMessage());model.addAttribute("currentPath",request.getRequestURI());model.addAttribute("me",p==null?null:tx.execute(s->db.first("from NguoiDung u where u.email=:e",NguoiDung.class,"e",p.getName()).map(Global::view).orElse(null)));var match=java.util.regex.Pattern.compile("^/ke-hoach-moc/(thue|de-xuat)/([1-9][0-9]*)(?:/.*)?$").matcher(request.getRequestURI());model.addAttribute("back",match.matches()?url(match.group(1),Long.valueOf(match.group(2))):"/ke-hoach-moc");return "milestone-error";}
    @GetMapping("/ke-hoach-moc") String list(Principal p,@RequestParam(defaultValue="1")String trang,Model model){model.addAttribute("workspace",plans.workspace(actor(p),CatalogDiscovery.Filter.page(trang)));return "milestone-list";}
    @GetMapping("/ke-hoach-moc/{kind}/{sourceId}") String details(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam(defaultValue="1")String trangLichSu,Model model){model.addAttribute("plan",plans.details(actor(p),kind,sourceId,CatalogDiscovery.Filter.page(trangLichSu)));return "milestone-detail";}
    @GetMapping("/ke-hoach-moc/{kind}/{sourceId}/thiet-lap") String editor(Principal p,@PathVariable String kind,@PathVariable Long sourceId,HttpSession session,Model model){Long actor=actor(p);var view=plans.details(actor,kind,sourceId,1);if(!view.canEdit())throw new AccessDeniedException("Bạn chưa có lượt thiết lập hoặc điều chỉnh mốc.");var form=view.latest()==null?new MilestonePlanForm():MilestonePlanRules.form(view.latest().terms());form.setReason("");if(form.getItems().isEmpty())form.getItems().add(new MilestonePlanForm.Item());model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));model.addAttribute("planForm",form);model.addAttribute("token",remember(session,"SANG_PLAN_INTENTS",intent(actor,view)));model.addAttribute("step",1);return "milestone-editor";}
    @PostMapping("/ke-hoach-moc/{kind}/{sourceId}/ra-soat") String review(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam String token,@ModelAttribute("planForm")MilestonePlanForm form,BindingResult binding,HttpServletRequest request,HttpSession session,Model model){
        Long actor=actor(p);var intent=stored(session,"SANG_PLAN_INTENTS",token,Intent.class);authority(intent,actor,kind,sourceId);var view=plans.details(actor,kind,sourceId,1);model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));
        try{bound(binding,request,BUSINESS);var terms=plans.preview(actor,kind,sourceId,intent.fingerprint(),intent.version(),form);return review(model,new Ticket(intent,"SEND",terms,null),remember(session,"SANG_PLAN_TICKETS",new Ticket(intent,"SEND",terms,null)));}
        catch(BusinessException error){model.addAttribute("formError",error.getMessage());model.addAttribute("token",token);model.addAttribute("step",2);model.addAttribute("unsent",true);return "milestone-editor";}
    }
    private String review(Model model,Ticket ticket,String token){model.addAttribute("ticketAction",ticket.action());model.addAttribute("terms",ticket.terms());model.addAttribute("reason",ticket.reason());model.addAttribute("token",token);var view=(MilestonePlanService.View)model.asMap().get("plan");if(ticket.action().equals("SEND")&&view.latest()!=null){var old=new LinkedHashMap<String,MilestonePlanRules.Item>();view.latest().terms().items().forEach(i->old.put(i.stableKey(),i));var changes=new LinkedHashMap<String,String>();for(var item:ticket.terms().items()){var previous=old.remove(item.stableKey());changes.put("Mốc "+item.position()+" · "+item.title(),previous==null?"Thêm mốc":previous.equals(item)?"Giữ nguyên":"Sửa mốc");}model.addAttribute("changes",changes);model.addAttribute("removed",old.values());}return "milestone-review";}
    @GetMapping("/ke-hoach-moc/{kind}/{sourceId}/sua") String back(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam String token,HttpSession session,Model model){var ticket=stored(session,"SANG_PLAN_TICKETS",token,Ticket.class);authority(ticket.intent(),actor(p),kind,sourceId);Checks.require(ticket.action().equals("SEND"),"Không có nội dung mốc cần sửa.");var view=plans.details(actor(p),kind,sourceId,1);if(!view.canEdit()||view.current()!=ticket.intent().version())throw new BusinessException("Kế hoạch đã thay đổi. Hãy mở lại bản mới.");model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));model.addAttribute("planForm",MilestonePlanRules.form(ticket.terms()));model.addAttribute("token",remember(session,"SANG_PLAN_INTENTS",ticket.intent()));model.addAttribute("step",2);model.addAttribute("unsent",true);return "milestone-editor";}
    @GetMapping("/ke-hoach-moc/{kind}/{sourceId}/chap-nhan") String accept(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam int phienBan,HttpSession session,Model model){Long actor=actor(p);var view=plans.details(actor,kind,sourceId,1);Checks.require(view.current()==phienBan,"Phiên bản đã thay đổi. Hãy tải lại bản mới nhất.");if(!view.canRespond())throw new AccessDeniedException("Bạn không có lượt chấp nhận kế hoạch.");var ticket=new Ticket(intent(actor,view),"ACCEPT",view.latest().terms(),null);model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));return review(model,ticket,remember(session,"SANG_PLAN_TICKETS",ticket));}
    @GetMapping("/ke-hoach-moc/{kind}/{sourceId}/huy") String cancel(Principal p,@PathVariable String kind,@PathVariable Long sourceId,HttpSession session,Model model){Long actor=actor(p);var view=plans.details(actor,kind,sourceId,1);if(!view.canCancel())throw new AccessDeniedException("Kế hoạch không thể hủy thương lượng.");model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));model.addAttribute("cancelForm",new CancelForm());model.addAttribute("token",remember(session,"SANG_PLAN_INTENTS",intent(actor,view)));return "milestone-cancel";}
    @PostMapping("/ke-hoach-moc/{kind}/{sourceId}/huy/ra-soat") String reviewCancel(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam String token,@ModelAttribute("cancelForm")CancelForm form,BindingResult binding,HttpServletRequest request,HttpSession session,Model model){Long actor=actor(p);var intent=stored(session,"SANG_PLAN_INTENTS",token,Intent.class);authority(intent,actor,kind,sourceId);var view=plans.details(actor,kind,sourceId,1);if(!view.canCancel())throw new AccessDeniedException("Kế hoạch không thể hủy thương lượng.");Checks.require(intent.version()==view.current(),"Phiên bản đã thay đổi. Hãy tải lại kế hoạch.");model.addAttribute("plan",view);model.addAttribute("monthEndOffset",MilestonePlanRules.monthEndOffset(view.source().days()));try{bound(binding,request,Set.of("reason"));String reason=Checks.text(form.getReason(),5,2000,"Lý do hủy");var ticket=new Ticket(intent,"CANCEL",null,reason);return review(model,ticket,remember(session,"SANG_PLAN_TICKETS",ticket));}catch(BusinessException error){model.addAttribute("formError",error.getMessage());model.addAttribute("token",token);return "milestone-cancel";}}
    @PostMapping("/ke-hoach-moc/{kind}/{sourceId}/xac-nhan") String confirm(Principal p,@PathVariable String kind,@PathVariable Long sourceId,@RequestParam String token,HttpSession session,HttpServletRequest request,RedirectAttributes redirect){Long actor=actor(p);var ticket=stored(session,"SANG_PLAN_TICKETS",token,Ticket.class);authority(ticket.intent(),actor,kind,sourceId);Checks.require(request.getParameterMap().keySet().stream().allMatch(Set.of("token","_csrf")::contains),"Biểu mẫu chứa trường không được phép cập nhật.");var intent=ticket.intent();switch(ticket.action()){case "SEND"->plans.send(actor,kind,sourceId,intent.fingerprint(),intent.version(),intent.operation(),ticket.terms());case "ACCEPT"->plans.accept(actor,kind,sourceId,intent.fingerprint(),intent.version());case "CANCEL"->plans.cancel(actor,kind,sourceId,intent.fingerprint(),intent.version(),ticket.reason());default->throw new BusinessException("Thao tác không hợp lệ.");}redirect.addFlashAttribute("success",ticket.action().equals("SEND")?"Đã gửi kế hoạch mốc đến bên còn lại.":ticket.action().equals("ACCEPT")?"Đã thống nhất mốc — Chờ lập hợp đồng.":"Đã hủy thương lượng mốc. Lịch sử được giữ nguyên.");return "redirect:"+url(kind,sourceId);}
}
